import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {upper_bound} targets await classification. Determine how many integers d with 1 <= d <= {upper_bound} can be written as m^2 - n^2 for integers 0 <= n < m <= {limit_m}, additionally requiring that m - n is a multiple of {mod_k}, and counting only those d that admit at least {min_reps} distinct ordered pairs (m, n) satisfying all conditions.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Helper to count representations per d
def rep_counts(N, M, K):
    counts = [0]*(N+1)
    for d in range(1, N+1):
        # Quick parity exclusion: no representations when d % 4 == 2
        if d % 4 == 2:
            continue
        # Enumerate factor pairs a*b = d with a <= b
        a = 1
        while a * a <= d:
            if d % a == 0:
                b = d // a
                # same parity needed so that m=(a+b)/2, n=(b-a)/2 are integers
                if ((a + b) % 2) == 0:
                    # enforce m - n = a to be multiple of K
                    if a % K == 0:
                        # compute m; bound by M suffices since n <= m automatically
                        m = (a + b) // 2
                        if m <= M:
                            counts[d] += 1
            a += 1
    return counts
# Try random instances until difficulty constraints are met
for _ in range(100):
    M = rng.randint(40, 300)
    # Keep upper_bound within feasible difference range
    N_low = max(10, int(0.35 * M * M))
    N_high = M * M
    upper = rng.randint(N_low, N_high)
    K = rng.choice([1, 2, 3, 4, 6, 8])
    R = rng.choice([2, 2, 2, 3])
    counts = rep_counts(upper, M, K)
    qual = sum(1 for d in range(1, upper+1) if counts[d] >= R)
    has_more = any(counts[d] >= R+1 for d in range(1, upper+1))
    has_zero = any(counts[d] == 0 for d in range(1, upper+1))
    # Difficulty and non-triviality filters
    # - ensure some but not nearly all d qualify
    # - ensure at least one d has more than R representations
    # - ensure existence of non-representable numbers
    if 5 <= qual <= upper - max(10, upper//10) and has_more and has_zero:
        return {'upper_bound': upper, 'limit_m': M, 'mod_k': K, 'min_reps': R}
# Fallback deterministic construction if random retries fail
M = 120
upper = 10000
K = 4
R = 2
return {'upper_bound': upper, 'limit_m': M, 'mod_k': K, 'min_reps': R}

    def verifier(assign):
# Validate presence and types
try:
    N = int(assign['upper_bound'])
    M = int(assign['limit_m'])
    K = int(assign['mod_k'])
    R = int(assign['min_reps'])
except Exception:
    # Missing or non-integer parameters
    return (False, None)  # invalid assignment
# Domain checks
if N <= 0 or M <= 0 or K <= 0 or R <= 0:
    # All parameters must be positive
    return (False, None)
if R < 2:
    # Enforce non-trivial multiplicity to avoid seed-like simplicity
    return (False, None)
if N > M * M:
    # Keep the search interval within feasible difference range to avoid trivial tail
    return (False, None)
# Count representations for each d
def rep_count_for_d(d, M, K):
    if d % 4 == 2:
        return 0
    cnt = 0
    a = 1
    while a * a <= d:
        if d % a == 0:
            b = d // a
            # require same parity so m, n are integers
            if ((a + b) % 2) == 0:
                # m - n = a must be multiple of K
                if a % K == 0:
                    m = (a + b) // 2
                    # n = (b - a)//2 >= 0 automatically when a <= b
                    if m <= M:
                        cnt += 1
        a += 1
    return cnt
counts = [0]*(N+1)
for d in range(1, N+1):
    counts[d] = rep_count_for_d(d, M, K)
answer = sum(1 for d in range(1, N+1) if counts[d] >= R)
# Difficulty enforcement: ensure instance is not trivial
if answer < 5 or answer > N - max(10, N//10):
    # Too few or almost all qualify; reject as trivial
    return (False, None)
if not any(c >= R+1 for c in counts[1:]):
    # No d exceeds the threshold, making counting by simple parity nearly sufficient
    return (False, None)
if not any(c == 0 for c in counts[1:]):
    # Every d qualifies or has at least one representation; too easy
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

